const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const f = $('Add Team Form').first().json;
const grouped = f.grouped === 'Yes';
let interval = null;
if (grouped) {
  const raw = $('Grouping Interval Form').first().json.grouping_interval;
  interval = parseInt(raw, 10);
  if (!Number.isInteger(interval) || interval < 1) throw new Error('Grouping interval must be a whole number of minutes >= 1');
}
const voiceUrl = String(f.voice_url || '').trim();
if (!voiceUrl) throw new Error('Voice file path / URL is required');
const nodeOwner = String(f.node_owner || '').trim();
const dept = f.department;
const summary = `<div style='background:#fffaf0;padding:20px;border-radius:10px;border:2px solid #ffcc00;font-family:sans-serif;'><h2 style='color:#cc3300;margin-top:0;'>⚠️ Review Before Adding Team</h2>
<div style='background:white;padding:15px;border-radius:5px;border:1px solid #eee;line-height:1.8;'>
<p><b>👥 Node Owner:</b> ${esc(nodeOwner)}</p>
<p><b>🔗 Grouped:</b> ${grouped ? 'Yes' : 'No'}</p>
<p><b>⏱️ Grouping Interval:</b> ${grouped ? interval + ' min' : 'N/A'}</p>
<p><b>🔊 Voice URL:</b> ${esc(voiceUrl)}</p>
<p><b>🏢 Department:</b> ${esc(dept)}</p></div>
<p style='font-weight:bold;color:#cc3300;'>Choose Confirm and click Submit to add this team.</p></div>`;
return [{ json: { node_owner: nodeOwner, grouped, grouped_flag: grouped ? 1 : 0, grouping_interval: interval, voice_url: voiceUrl, department: dept, summary_html: summary } }];

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows = $input.all().map(i => i.json).filter(r => r && r.NAME);
const opts = rows.length ? rows.map(r => ({ option: String(r.NAME) })) : [{ option: 'No active teams found' }];
const fields = [{ fieldLabel: 'Select Team to Remove', fieldType: 'dropdown', fieldOptions: opts, requiredField: true }];
